BEGIN;
CREATE TABLE schema_migration(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TYPE app_role AS ENUM ('ADMIN','WAREHOUSE','SALES'); CREATE TYPE barcode_role AS ENUM ('CURRENT','HISTORICAL'); CREATE TYPE barcode_status AS ENUM ('ACTIVE','QUARANTINED','RETIRED'); CREATE TYPE document_type AS ENUM ('TRANSFER','SALE','RETURN_EXCHANGE','ADJUSTMENT','HISTORICAL_SALE'); CREATE TYPE document_status AS ENUM ('DRAFT','APPROVED','UNAPPROVED','COMPLETED','REVERSED','NO_CHANGE'); CREATE TYPE import_status AS ENUM ('UPLOADED','INSPECTED','VALIDATED','NEEDS_REVIEW','READY','COMMITTED','FAILED'); CREATE TYPE mapping_decision AS ENUM ('AUTO_CANDIDATE','CONFIRMED','REJECTED','CONFLICT');
CREATE TABLE category(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid REFERENCES category(id) ON DELETE RESTRICT, code text NOT NULL, code_normalized text NOT NULL, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 0, UNIQUE(parent_id,code_normalized)); CREATE UNIQUE INDEX category_root_code_uq ON category(code_normalized) WHERE parent_id IS NULL;
CREATE TABLE brand(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, enabled boolean NOT NULL DEFAULT true); CREATE TABLE unit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, quantity_scale smallint NOT NULL DEFAULT 0 CHECK(quantity_scale BETWEEN 0 AND 4), enabled boolean NOT NULL DEFAULT true); CREATE TABLE fit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, enabled boolean NOT NULL DEFAULT true); CREATE TABLE counterparty(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, enabled boolean NOT NULL DEFAULT true); CREATE TABLE warehouse(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, type text NOT NULL, enabled boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 0);
CREATE TABLE spec_dimension(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, enabled boolean NOT NULL DEFAULT true); CREATE TABLE spec_value(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dimension_id uuid NOT NULL REFERENCES spec_dimension(id) ON DELETE RESTRICT, code text NOT NULL, code_normalized text NOT NULL, name text NOT NULL, sort_order integer NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, UNIQUE(dimension_id,code_normalized), UNIQUE(id,dimension_id)); CREATE TABLE size_group(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, enabled boolean NOT NULL DEFAULT true); CREATE TABLE size_group_item(size_group_id uuid NOT NULL REFERENCES size_group(id) ON DELETE CASCADE, spec_value_id uuid NOT NULL REFERENCES spec_value(id) ON DELETE RESTRICT, sort_order integer NOT NULL, PRIMARY KEY(size_group_id,spec_value_id), UNIQUE(size_group_id,sort_order));
CREATE TABLE barcode_scheme(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, enabled boolean NOT NULL DEFAULT true); CREATE TABLE barcode_scheme_version(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scheme_id uuid NOT NULL REFERENCES barcode_scheme(id) ON DELETE RESTRICT, version integer NOT NULL CHECK(version>0), published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scheme_id,version)); CREATE TABLE barcode_scheme_segment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scheme_version_id uuid NOT NULL REFERENCES barcode_scheme_version(id) ON DELETE RESTRICT, segment_order integer NOT NULL CHECK(segment_order>=0), type text NOT NULL, length integer NOT NULL CHECK(length>0), pad_side text CHECK(pad_side IN ('LEFT','RIGHT')), pad_char text CHECK(length(pad_char)=1), value_rule jsonb NOT NULL DEFAULT '{}'::jsonb, dimension_id uuid REFERENCES spec_dimension(id) ON DELETE RESTRICT, literal text, UNIQUE(scheme_version_id,segment_order));
CREATE TABLE product(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, category_id uuid NOT NULL REFERENCES category(id) ON DELETE RESTRICT, brand_id uuid REFERENCES brand(id) ON DELETE RESTRICT, unit_id uuid NOT NULL REFERENCES unit(id) ON DELETE RESTRICT, fit_id uuid REFERENCES fit(id) ON DELETE RESTRICT, counterparty_id uuid REFERENCES counterparty(id) ON DELETE RESTRICT, current_barcode_scheme_version_id uuid REFERENCES barcode_scheme_version(id) ON DELETE RESTRICT, enabled boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE product_option(product_id uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE, spec_value_id uuid NOT NULL REFERENCES spec_value(id) ON DELETE RESTRICT, PRIMARY KEY(product_id,spec_value_id)); CREATE TABLE variant(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES product(id) ON DELETE RESTRICT, option_key text NOT NULL, enabled boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 0, UNIQUE(product_id,option_key)); CREATE TABLE variant_option(variant_id uuid NOT NULL REFERENCES variant(id) ON DELETE RESTRICT, dimension_id uuid NOT NULL REFERENCES spec_dimension(id) ON DELETE RESTRICT, spec_value_id uuid NOT NULL, PRIMARY KEY(variant_id,dimension_id), UNIQUE(variant_id,spec_value_id), FOREIGN KEY(spec_value_id,dimension_id) REFERENCES spec_value(id,dimension_id) ON DELETE RESTRICT);
CREATE TABLE product_image(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES product(id) ON DELETE RESTRICT, path text NOT NULL, sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'), media_type text NOT NULL, sort_order integer NOT NULL DEFAULT 0); CREATE TABLE price_type(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, code_normalized text NOT NULL UNIQUE, name text NOT NULL, enabled boolean NOT NULL DEFAULT true); CREATE TABLE product_price(product_id uuid NOT NULL REFERENCES product(id) ON DELETE RESTRICT, price_type_id uuid NOT NULL REFERENCES price_type(id) ON DELETE RESTRICT, amount numeric(18,4) NOT NULL CHECK(amount>=0), PRIMARY KEY(product_id,price_type_id)); CREATE TABLE barcode_encoding_mapping(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scheme_version_id uuid NOT NULL REFERENCES barcode_scheme_version(id) ON DELETE RESTRICT, dimension_id uuid REFERENCES spec_dimension(id) ON DELETE RESTRICT, spec_value_id uuid REFERENCES spec_value(id) ON DELETE RESTRICT, product_id uuid REFERENCES product(id) ON DELETE RESTRICT, encoded_value text NOT NULL, UNIQUE NULLS NOT DISTINCT(scheme_version_id,dimension_id,spec_value_id,product_id)); CREATE TABLE barcode(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), value text NOT NULL UNIQUE, variant_id uuid NOT NULL REFERENCES variant(id) ON DELETE RESTRICT, status barcode_status NOT NULL, role barcode_role NOT NULL, scheme_version_id uuid REFERENCES barcode_scheme_version(id) ON DELETE RESTRICT, source text NOT NULL, generated_input_snapshot jsonb, quarantine_reason text, created_at timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX barcode_one_active_current_per_variant ON barcode(variant_id) WHERE status='ACTIVE' AND role='CURRENT';
CREATE TABLE app_user(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL UNIQUE, password_hash text NOT NULL, display_name text NOT NULL, role app_role NOT NULL, enabled boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE user_session(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE user_view_setting(user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, view_key text NOT NULL, settings jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,view_key)); CREATE TABLE system_setting(key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE business_document(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number text NOT NULL UNIQUE, type document_type NOT NULL, status document_status NOT NULL, document_date date NOT NULL, source_warehouse_id uuid REFERENCES warehouse(id) ON DELETE RESTRICT, target_warehouse_id uuid REFERENCES warehouse(id) ON DELETE RESTRICT, actor_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT, version integer NOT NULL DEFAULT 0, revision integer NOT NULL DEFAULT 1, inventory_mode text NOT NULL DEFAULT 'POSTING', original_document_id uuid REFERENCES business_document(id) ON DELETE RESTRICT, reversal_reason text, totals jsonb NOT NULL DEFAULT '{}'::jsonb, note text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(source_warehouse_id IS NULL OR target_warehouse_id IS NULL OR source_warehouse_id<>target_warehouse_id)); CREATE TABLE document_line(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES business_document(id) ON DELETE RESTRICT, variant_id uuid NOT NULL REFERENCES variant(id) ON DELETE RESTRICT, warehouse_id uuid REFERENCES warehouse(id) ON DELETE RESTRICT, direction text, barcode text, product_code text NOT NULL, product_name text NOT NULL, options_snapshot jsonb NOT NULL, color_name text, size_name text, unit_name text NOT NULL, quantity numeric(18,4) NOT NULL CHECK(quantity>0), unit_price numeric(18,4) CHECK(unit_price>=0), retail_price numeric(18,4) CHECK(retail_price>=0), amount numeric(18,2), historical_returned_quantity numeric(18,4) NOT NULL DEFAULT 0 CHECK(historical_returned_quantity>=0), note text); CREATE TABLE return_line_reference(return_line_id uuid PRIMARY KEY REFERENCES document_line(id) ON DELETE RESTRICT, original_sale_line_id uuid NOT NULL REFERENCES document_line(id) ON DELETE RESTRICT); CREATE INDEX return_line_original_idx ON return_line_reference(original_sale_line_id);
CREATE TABLE inventory_posting(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_key text NOT NULL UNIQUE, business_type text NOT NULL, document_id uuid NOT NULL REFERENCES business_document(id) ON DELETE RESTRICT, action text NOT NULL, status text NOT NULL, reversal_of_posting_id uuid REFERENCES inventory_posting(id) ON DELETE RESTRICT, actor_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX posting_one_reversal ON inventory_posting(reversal_of_posting_id) WHERE reversal_of_posting_id IS NOT NULL; CREATE TABLE inventory_balance(variant_id uuid NOT NULL REFERENCES variant(id) ON DELETE RESTRICT, warehouse_id uuid NOT NULL REFERENCES warehouse(id) ON DELETE RESTRICT, quantity numeric(18,4) NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 0, PRIMARY KEY(variant_id,warehouse_id)); CREATE TABLE inventory_movement(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), posting_id uuid NOT NULL REFERENCES inventory_posting(id) ON DELETE RESTRICT, document_id uuid NOT NULL REFERENCES business_document(id) ON DELETE RESTRICT, document_line_id uuid REFERENCES document_line(id) ON DELETE RESTRICT, variant_id uuid NOT NULL REFERENCES variant(id) ON DELETE RESTRICT, warehouse_id uuid NOT NULL REFERENCES warehouse(id) ON DELETE RESTRICT, delta numeric(18,4) NOT NULL CHECK(delta<>0), balance_after numeric(18,4) NOT NULL, business_type text NOT NULL, reversal_of uuid REFERENCES inventory_movement(id) ON DELETE RESTRICT, occurred_at timestamptz NOT NULL DEFAULT now(), actor_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT); CREATE UNIQUE INDEX movement_one_reversal ON inventory_movement(reversal_of) WHERE reversal_of IS NOT NULL; CREATE TABLE idempotency_request(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT, command_scope text NOT NULL, idempotency_key text NOT NULL, payload_hash text NOT NULL, response jsonb, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor_id,command_scope,idempotency_key));
CREATE TABLE import_batch(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), file_name text NOT NULL, sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'), importer_version text NOT NULL, status import_status NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), committed_at timestamptz); CREATE TABLE source_record(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES import_batch(id) ON DELETE RESTRICT, source_type text NOT NULL, sheet_name text NOT NULL, row_number integer NOT NULL CHECK(row_number>0), column_name text, raw_value jsonb, source_key text NOT NULL, UNIQUE(batch_id,source_key)); CREATE TABLE source_mapping(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_record_id uuid NOT NULL REFERENCES source_record(id) ON DELETE RESTRICT, target_type text NOT NULL, target_id uuid, decision mapping_decision NOT NULL, evidence jsonb NOT NULL DEFAULT '[]'::jsonb, decided_by uuid REFERENCES app_user(id) ON DELETE RESTRICT, decided_at timestamptz); CREATE TABLE migration_issue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES import_batch(id) ON DELETE RESTRICT, source_record_id uuid REFERENCES source_record(id) ON DELETE RESTRICT, code text NOT NULL, severity text NOT NULL, details jsonb NOT NULL, resolved_at timestamptz, resolved_by uuid REFERENCES app_user(id) ON DELETE RESTRICT); CREATE TABLE migration_checkpoint(batch_id uuid NOT NULL REFERENCES import_batch(id) ON DELETE RESTRICT, stage text NOT NULL, cursor jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(batch_id,stage)); CREATE TABLE opening_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ledger_key text NOT NULL UNIQUE DEFAULT 'CURRENT', batch_id uuid NOT NULL UNIQUE REFERENCES import_batch(id) ON DELETE RESTRICT, committed_at timestamptz NOT NULL DEFAULT now(), CHECK(ledger_key='CURRENT'));
INSERT INTO schema_migration(version) VALUES ('0001_database_baseline'); COMMIT;
